import{_ as a,o as e,a as r,b as d}from"./app.DKoEZOcr.js";const l="/ascendc.github.io/pr/5487/assets/address_overlap_unsupported.XPeiarSp.png",f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"通用说明和约束","link":"/api/SIMD-API/general_description_and_constraints"}]},"headers":[],"relativePath":"api/SIMD-API/general_description_and_constraints.md","filePath":"api/SIMD-API/general_description_and_constraints.md","outlineHeaders":[{"level":2,"title":"所需头文件和库文件","slug":"所需头文件和库文件","link":"#所需头文件和库文件"},{"level":2,"title":"逻辑位置和物理存储的映射关系","slug":"逻辑位置和物理存储的映射关系","link":"#逻辑位置和物理存储的映射关系"},{"level":2,"title":"通用地址对齐约束","slug":"通用地址对齐约束","link":"#通用地址对齐约束"},{"level":2,"title":"通用地址重叠约束","slug":"通用地址重叠约束","link":"#通用地址重叠约束"}],"lastUpdated":1787050286000}'),s={name:"api/SIMD-API/general_description_and_constraints.md"};function i(o,t,n,A,c,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<div><article class="markdown-body"><h1>通用说明和约束<span id="ZH-CN_TOPIC_0000001714258422"></span></h1><h2 id="所需头文件和库文件">所需头文件和库文件<span id="section1299152225418"></span><a class="header-anchor" href="#所需头文件和库文件">​</a></h2><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 Ascend C API 所在头文件目录为：</p><ul><li>基础API：<code>${INSTALL_DIR}/asc/include/basic_api</code></li><li>高阶API：（注意，如下目录头文件中包含的接口如果未在资料中声明，属于间接调用接口，开发者无需关注） <ul><li><code>${INSTALL_DIR}/asc/include/adv_api</code></li><li><code>${INSTALL_DIR}/asc/include/tiling</code></li></ul></li></ul><p><code>${INSTALL_DIR}</code> 请替换为 CANN 软件安装后文件存储路径。以 root 用户安装为例，安装后文件默认存储路径为：<code>/usr/local/Ascend/cann</code>。</p><p>使用 Ascend C API 依赖的库文件说明如下：</p><ul><li>基础API：不涉及</li><li>高阶API：因高阶 API 配套 Host Tiling 接口，需要链接 <code>libtiling_api.a</code>。</li></ul></div><p>为方便开发者使用，Ascend C基础API和高阶API均支持通过包含kernel_operator.h文件来调用相应接口。如无特殊说明，包含该头文件即可满足接口调用需求。若API文档中有特殊说明，则应遵循API的具体说明。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>#include &quot;kernel_operator.h&quot;\n</code></pre></div><h2 id="逻辑位置和物理存储的映射关系">逻辑位置和物理存储的映射关系<span id="section1359919519819"></span><a class="header-anchor" href="#逻辑位置和物理存储的映射关系">​</a></h2><p>Ascend C API的操作数通常为<a href="basic_api/data_structures/GlobalTensor/GlobalTensor.html">GlobalTensor</a>和<a href="basic_api/data_structures/LocalTensor/LocalTensor.html">LocalTensor</a>，Tensor数据的存储位置均使用逻辑位置（<a href="basic_api/aux_data_structures/TPosition.html">TPosition</a>）来表达，从而隐藏了硬件架构的差异。TPosition类型包括：VECIN、VECOUT、VECCALC、A1、A2、B1、B2、CO1、CO2等，其与物理内存的映射关系如下表所示。</p><p><strong>表1</strong> TPosition与物理内存映射关系</p><p><span id="table07372185712"></span></p><table><thead><tr><th>TPosition</th><th>物理内存</th></tr></thead><tbody><tr><td>GM</td><td>Global Memory</td></tr><tr><td>VECIN</td><td>UB</td></tr><tr><td>VECCALC</td><td>UB</td></tr><tr><td>VECOUT</td><td>UB</td></tr><tr><td>A1</td><td>L1 Buffer</td></tr><tr><td>A2</td><td>L0A Buffer</td></tr><tr><td>B1</td><td>L1 Buffer</td></tr><tr><td>B2</td><td>L0B Buffer</td></tr><tr data-filter="950"><td>C1</td><td>Ascend 950PR/Ascend 950DT，L1 Buffer。<br>Atlas 训练系列产品，Unified Buffer（UB）。<br>Atlas 推理系列产品AI Core，UB。<br>Atlas A2 训练系列产品/Atlas A2 推理系列产品，L1 Buffer。<br>Atlas A3 训练系列产品/Atlas A3 推理系列产品，L1 Buffer。<br>Atlas 200I/500 A2 推理产品，UB。</td></tr><tr data-filter="950"><td>C2</td><td>Ascend 950PR/Ascend 950DT，BiasTable Buffer。<br>Atlas 训练系列产品，L0C Buffer。<br>Atlas 推理系列产品AI Core，L0C Buffer。<br>Atlas A2 训练系列产品/Atlas A2 推理系列产品，BiasTable Buffer。<br>Atlas A3 训练系列产品/Atlas A3 推理系列产品，BiasTable Buffer。<br>Atlas 200I/500 A2 推理产品，BiasTable Buffer。</td></tr><tr><td>CO1</td><td>L0C Buffer</td></tr><tr data-filter="950"><td>CO2</td><td>Ascend 950PR/Ascend 950DT，Global Memory。<br>Atlas 训练系列产品，UB。<br>Atlas 推理系列产品AI Core，UB。<br>Atlas A2 训练系列产品/Atlas A2 推理系列产品，Global Memory。<br>Atlas A3 训练系列产品/Atlas A3 推理系列产品，Global Memory。<br>Atlas 200I/500 A2 推理产品，Global Memory。</td></tr><tr><td>TSCM</td><td>L1 Buffer</td></tr><tr data-filter="950"><td>SPM</td><td>Ascend 950PR/Ascend 950DT，Global Memory。<br>Atlas 训练系列产品，L1 Buffer。<br>Atlas 推理系列产品AI Core，L1 Buffer。<br>Atlas A2 训练系列产品/Atlas A2 推理系列产品，Global Memory。<br>Atlas A3 训练系列产品/Atlas A3 推理系列产品，Global Memory。</td></tr><tr data-filter="950"><td>C2PIPE2GM</td><td>Ascend 950PR/Ascend 950DT，Fixpipe Buffer。<br>Atlas A2 训练系列产品/Atlas A2 推理系列产品，Fixpipe Buffer。<br>Atlas A3 训练系列产品/Atlas A3 推理系列产品，Fixpipe Buffer。</td></tr></tbody></table><h2 id="通用地址对齐约束">通用地址对齐约束<span id="section796754519912"></span><a class="header-anchor" href="#通用地址对齐约束">​</a></h2><p>AI Core上的存储单元用于存储矢量计算、矩阵计算的源操作数和目的操作数，各类存储单元的对齐要求如<a href="#table16278354141117">表2</a>所示，因此Ascend C API操作数的起始地址对齐要求应与这些存储单元的对齐要求保持一致。<strong>需要注意的是，如果接口中已明确说明操作数起始地址对齐要求，则以具体API中的说明为准。</strong></p><p><strong>表2</strong> 不同存储单元的对齐要求</p><p><span id="table16278354141117"></span></p><table><thead><tr><th>存储单元</th><th>对齐要求</th></tr></thead><tbody><tr><td>Global Memory</td><td>无对齐要求。</td></tr><tr><td>UB</td><td>32Byte对齐。</td></tr><tr><td>L1 Buffer</td><td>32Byte对齐。</td></tr><tr><td>L0A Buffer/L0B Buffer</td><td>512Byte对齐。</td></tr><tr><td>L0C Buffer</td><td>64Byte对齐。</td></tr><tr><td>BiasTable Buffer</td><td>64Byte对齐。</td></tr><tr><td>Fixpipe Buffer</td><td>64Byte对齐。</td></tr></tbody></table><h2 id="通用地址重叠约束">通用地址重叠约束<span id="section668772811100"></span><a class="header-anchor" href="#通用地址重叠约束">​</a></h2><p>使用基础API的Tensor高维切分计算接口时，为了节省地址空间，开发者可以定义一个Tensor，供源操作数与目的操作数同时使用（即地址重叠）。使用时需要注意以下约束：</p><ul><li>单次迭代内：源操作数与目的操作数必须100%完全重叠，不支持部分重叠。</li><li>多次迭代间：不支持前序迭代的目的操作数与后序迭代的源操作数重叠。例如，第N次迭代的目的操作数是第N+1次的源操作数（如下图所示）。在这种情况下，第N次迭代可能会改写覆盖源操作数的数值，导致无法得到预期结果。特别地，对于部分双目计算类的API（Add、Sub、Mul、Max、Min、AddRelu、SubRelu），当数据类型为half、int32_t、float时，支持前序迭代的目的操作数与后序迭代的源操作数重叠：仅针对目的操作数和第二个源操作数重叠的情况，且src1RepStride或者dstRepStride必须为0。</li></ul><p><strong>图1</strong> 地址重叠示例（不支持）<span id="fig12654416181216"></span><br><img src="'+l+'" alt title="地址重叠示例（不支持）"></p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本节所述地址重叠通用约束适用于一般情况，API参考中如有额外特殊说明的，则以具体API中的说明为准。 API中没有描述地址重叠约束的，视为不支持Tensor高维切分计算的地址重叠，地址重叠时计算结果可能不满足预期。</p></div></article></div>',1)])])}const u=a(s,[["render",i]]);export{f as __pageData,u as default};
